server.registerTool(
  "check_fold",
  {
    title: "Check Fold",
    description: "Renders a URL and reports what its fold actually is: a screenshot, the composition class it belongs to, drift from the class you set out to build, three judged invariants, and four measurements reported WITHOUT a verdict. The unjudged four (identification, single dominance, asymmetry, restraint budget) are measured but not scored: calibration against reference landing pages showed those thresholds do not yet discriminate, so they are yours to interpret. Treat the screenshot as the primary output \u2014 look at it. Invariant 7 (a costly detail) is unmeasurable by construction: pass what you committed to as `costly_detail`, or it fails. Needs a browser: install puppeteer, or set UI_CRAFT_CHROME to an existing Chrome to skip the download.",
    inputSchema: {
      url: z.string().describe("URL of the rendered page \u2014 a local dev server URL is fine"),
      costly_detail: z.string().optional().describe("The one element of this fold that could not have come from a template, and what it cost"),
      expected_class: z.string().optional().describe("The composition class you set out to build, to detect drift"),
      width: z.number().int().optional().describe("Viewport width (default 1440)"),
      height: z.number().int().optional().describe("Viewport height (default 900)")
    },
    outputSchema: {
      url: z.string().optional(),
      composition: z.object({ id: z.string(), confidence: z.string(), why: z.string() }).optional(),
      expected_class: z.string().nullable().optional(),
      drift: z.string().nullable().optional(),
      checks: z.array(
        z.object({ id: z.number(), name: z.string(), pass: z.boolean(), detail: z.string() })
      ),
      observations: z.array(z.object({ id: z.number(), name: z.string(), value: z.string(), note: z.string() })).optional(),
      summary: z.object({ passed: z.number(), total: z.number(), ok: z.boolean() }).optional(),
      measured: z.unknown().optional(),
      error: z.string().optional()
    }
  },
  async (args) => {
    let result;
    try {
      result = await checkFold(args);
    } catch (e) {
      result = { error: `Unexpected error: ${e?.message ?? String(e)}`, checks: [] };
    }
    const isError = Boolean(result.error);
    const { screenshot, ...structured } = result;
    return {
      content: [
        { type: "text", text: JSON.stringify(structured, null, 2) },
        ...screenshot ? [{ type: "image", data: screenshot, mimeType: "image/png" }] : []
      ],
      ...isError ? {} : { structuredContent: structured },
      isError
    };
  }
);
